Here's an example C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string wordToCount; // user input word to count
    std::string currentLine; // current line being read from file

    std::cout << "Enter the word to count: ";
    std::cin >> wordToCount;

    std::ifstream inputFile("input_file.txt"); // replace with the name of your input file

    int count = 0; // initialize count to 0

    if (inputFile.is_open()) {
        while (getline(inputFile, currentLine)) { // read each line of the file
            size_t pos = 0;
            while ((pos = currentLine.find(wordToCount, pos)) != std::string::npos) { // find all occurrences of the word
                count++; // increment count for each occurrence
                pos += wordToCount.length(); // move to the next position after the word
            }
        }
        inputFile.close();
    } else {
        std::cerr << "Unable to open input file." << std::endl;
        return 1;
    }

    std::cout << "The word \"" << wordToCount << "\" appears " << count << " times in the file." << std::endl;

    return 0;
}
```

